import type {
  LibraryProject,
  ProjectLibrarySnapshot,
} from '../types/project-library';
import type { HubNavigationTarget } from './HubNavigation';
import { LibraryError } from './libraryErrors';
import fs from 'fs';
import { installationChannel } from '../install/installationChannel';
import path from 'path';
import {
  ProjectRegistry,
  libraryRoot,
  type RegisteredProject,
} from './ProjectRegistry';
import { importProject, type ProjectImportResult } from './ProjectImport';
import { BundleMetadataStore } from '../storage/library/BundleMetadataStore';
import { ProjectStorage } from './ProjectStorage';
import { TreeStore } from './TreeStore';
import {
  VariantHistoryService,
  type VariantHistoryEntry,
  type VariantHistoryDetail,
  type VariantHistorySummary,
} from './VariantHistoryService';
import { nestedFreshSessionWorkdirs } from './historyRoots';
import { errorMessage } from '../utils/errorMessage';
import type { VariantHistoryManifest } from '../types/variant-history';

export interface LibraryVariant extends VariantHistoryEntry {
  projectId: string;
  projectPath: string;
}
interface HistoryOwner {
  history: VariantHistoryService;
  storage: ProjectStorage;
  bundle?: BundleMetadataStore;
}
interface VariantReference {
  projectId: string;
  sessionId: string;
  variantId: string;
}
interface LibraryListOptions {
  isRemovedIncluded?: boolean;
}

export const currentLibraryRoot = (
  env: NodeJS.ProcessEnv = process.env,
): string => {
  const channel = installationChannel(env);
  return env.RIVET_LIBRARY_ROOT
    ? path.resolve(env.RIVET_LIBRARY_ROOT)
    : libraryRoot({ channel });
};

const isSameDirection = (
  left: VariantHistoryManifest,
  right: VariantHistoryManifest,
): boolean =>
  (!left.directionRef ||
    !right.directionRef ||
    left.directionRef === right.directionRef) &&
  JSON.stringify({ ...left, directionRef: undefined }) ===
    JSON.stringify({ ...right, directionRef: undefined });

export class ProjectLibrary {
  private readonly owners = new Map<string, Promise<HistoryOwner>>();
  readonly issues = new Map<string, string>();
  private readonly historyIssues = new Map<string, string>();
  private isClosed = false;
  private constructor(
    readonly registry: ProjectRegistry,
    private readonly isReadOnly = false,
  ) {}

  static async open(root = currentLibraryRoot()): Promise<ProjectLibrary> {
    return new ProjectLibrary(await ProjectRegistry.open(root));
  }

  static openReadOnly(root = currentLibraryRoot()): ProjectLibrary | null {
    const registry = ProjectRegistry.openReadOnly(root);
    return registry ? new ProjectLibrary(registry, true) : null;
  }

  async prepare(
    projectPath: string,
  ): Promise<{ project: RegisteredProject; migration: ProjectImportResult }> {
    const project = this.registry.register({
      projectPath,
      isExplicitOpen: true,
    });
    for (const nested of nestedFreshSessionWorkdirs(project.projectPath))
      this.registry.attachHistoryRoot({
        projectId: project.id,
        projectPath: nested,
      });
    let migration: ProjectImportResult;
    try {
      migration = await importProject({
        registry: this.registry,
        projectId: project.id,
      });
    } catch (error) {
      migration = {
        status: 'deferred',
        reason: errorMessage(error),
      };
    }
    if (project.storageKind !== this.registry.get(project.id).storageKind)
      await this.invalidate(project.id);
    if (migration.status === 'diverged' || migration.status === 'deferred')
      this.issues.set(
        project.id,
        migration.reason ??
          'Preserved source history differs from the imported bundle',
      );
    return { project: this.registry.get(project.id), migration };
  }

  async relink(args: {
    projectId: string;
    projectPath: string;
  }): Promise<RegisteredProject> {
    const project = this.registry.relink(args);
    await this.invalidate(project.id);
    this.issues.delete(project.id);
    this.historyIssues.delete(project.id);
    return project;
  }

  private async invalidate(projectId: string): Promise<void> {
    const pending = this.owners.get(projectId);
    this.owners.delete(projectId);
    if (!pending) return;
    const owner = await pending;
    owner.history.metadata.closeAll();
    owner.bundle?.close();
  }

  listProjects(): LibraryProject[] {
    return this.registry.list().map((project) => ({
      ...project,
      issue: this.historyIssues.get(project.id) ?? this.issues.get(project.id),
      historyIssue: this.historyIssues.get(project.id),
    }));
  }

  async snapshot(): Promise<ProjectLibrarySnapshot> {
    const variants = await this.listVariants();
    const projects = this.listProjects();
    const visibleIds = new Set(projects.map(({ id }) => id));
    return {
      projects,
      variants: variants
        .filter(({ projectId }) => visibleIds.has(projectId))
        .map(({ projectId, manifest, hasStaticPreview }) => ({
          projectId,
          sessionId: manifest.sessionId,
          variantId: manifest.variantId,
          label: manifest.label,
          brief: manifest.brief,
          createdAt: manifest.createdAt,
          hasStaticPreview,
          hasInteractivePreview: manifest.serve?.kind === 'dev-server',
        })),
    };
  }

  async updateVariant(
    args: VariantReference & { label?: string; status?: 'removed' },
  ): Promise<void> {
    const found = await this.variant(args);
    if (!found)
      throw new LibraryError('variant_not_found', 'Unknown saved direction');
    const target = { ...args, projectPath: found.projectPath };
    if (args.label !== undefined)
      await found.history.renameVariant({ ...target, label: args.label });
    if (args.status)
      await found.history.markStatus({ ...target, status: args.status });
  }

  async assertNavigationTarget(target: HubNavigationTarget): Promise<void> {
    if (target.projectId) this.registry.get(target.projectId);
    if (
      target.projectId &&
      target.sessionId &&
      target.variantId &&
      !(await this.variant({
        projectId: target.projectId,
        sessionId: target.sessionId,
        variantId: target.variantId,
      }))
    )
      throw new LibraryError('variant_not_found', 'Unknown saved direction');
  }

  async history(projectId: string): Promise<VariantHistoryService> {
    return (await this.owner(projectId)).history;
  }

  async attachGeneratedRoot({
    projectId,
    projectPath,
  }: {
    projectId: string;
    projectPath: string;
  }): Promise<void> {
    fs.mkdirSync(projectPath, { recursive: true });
    this.registry.attachHistoryRoot({ projectId, projectPath });
    const owner = await this.owner(projectId);
    if (!owner.bundle) return;
    const dataDirectory = this.registry.bundleDirectory(projectId);
    for (const root of new Set([
      path.resolve(projectPath),
      fs.realpathSync(projectPath),
    ])) {
      owner.storage.attach({
        projectPath: root,
        dataDirectory,
        cacheDirectory: path.join(this.registry.root, 'cache', projectId),
      });
    }
  }

  private async listProject(
    projectId: string,
    options: LibraryListOptions,
  ): Promise<LibraryVariant[]> {
    const project = this.registry.get(projectId);
    if (!project.isAvailable && project.storageKind === 'project')
      throw new Error(
        'Working folder and project-local history are unavailable',
      );
    const history = await this.history(projectId);
    const roots =
      project.storageKind === 'bundle'
        ? [project.projectPath]
        : this.registry.historyRoots(projectId);
    const entries = (
      await Promise.all(
        roots.map(async (projectPath) =>
          (
            await (this.isReadOnly
              ? history.listVariants({ projectPath })
              : history.listVariantsFromIndex({ projectPath }))
          ).map((entry) => ({ ...entry, projectId, projectPath })),
        ),
      )
    ).flat();
    const unique = new Map<string, LibraryVariant>();
    for (const entry of entries) {
      if (
        !options.isRemovedIncluded &&
        (entry.manifest.status === 'removed' ||
          entry.manifest.status === 'cancelled')
      )
        continue;
      const key = `${entry.manifest.sessionId}:${entry.manifest.variantId}`;
      const existing = unique.get(key);
      if (existing && !isSameDirection(existing.manifest, entry.manifest))
        throw new Error('Conflicting history identities across attached roots');
      unique.set(key, existing?.manifest.directionRef ? existing : entry);
    }
    return [...unique.values()];
  }

  async listVariants(
    projectId?: string,
    options: LibraryListOptions = {},
  ): Promise<LibraryVariant[]> {
    if (projectId) return this.listProject(projectId, options);
    const projects = this.registry.list();
    const results = await Promise.allSettled(
      projects.map((project) => this.listProject(project.id, options)),
    );
    return results
      .flatMap((result, index) => {
        if (result.status === 'fulfilled') {
          this.historyIssues.delete(projects[index].id);
          return result.value;
        }
        this.historyIssues.set(
          projects[index].id,
          result.reason instanceof Error
            ? result.reason.message
            : String(result.reason),
        );
        return [];
      })
      .sort((a, b) => b.manifest.createdAt.localeCompare(a.manifest.createdAt));
  }

  private async findVariant<T>(
    reference: VariantReference,
    read: (
      history: VariantHistoryService,
      projectPath: string,
    ) => Promise<T | null>,
  ): Promise<{
    value: T;
    projectPath: string;
    history: VariantHistoryService;
  } | null> {
    const project = this.registry.get(reference.projectId);
    const history = await this.history(project.id);
    const roots =
      project.storageKind === 'bundle'
        ? [project.projectPath]
        : this.registry.historyRoots(project.id);
    for (const projectPath of roots) {
      const value = await read(history, projectPath);
      if (value) return { value, projectPath, history };
    }
    return null;
  }

  async variantSummary(reference: VariantReference): Promise<{
    summary: VariantHistorySummary;
    projectPath: string;
  } | null> {
    const found = await this.findVariant(reference, (history, projectPath) =>
      history.getVariantSummary({ ...reference, projectPath }),
    );
    return found
      ? { summary: found.value, projectPath: found.projectPath }
      : null;
  }

  async variant(reference: VariantReference): Promise<{
    detail: VariantHistoryDetail;
    projectPath: string;
    history: VariantHistoryService;
  } | null> {
    const found = await this.findVariant(reference, (history, projectPath) =>
      history.getVariant({ ...reference, projectPath }),
    );
    return found
      ? {
          detail: found.value,
          projectPath: found.projectPath,
          history: found.history,
        }
      : null;
  }

  close(): void {
    if (this.isClosed) return;
    this.isClosed = true;
    for (const owner of this.owners.values())
      void owner.then(
        (value) => {
          value.history.metadata.closeAll();
          value.bundle?.close();
        },
        () => undefined,
      );
    this.registry.close();
  }

  private owner(projectId: string): Promise<HistoryOwner> {
    const existing = this.owners.get(projectId);
    if (existing) return existing;
    const pending = this.createOwner(projectId);
    this.owners.set(projectId, pending);
    void pending.catch(() => this.owners.delete(projectId));
    return pending;
  }

  private async createOwner(projectId: string): Promise<HistoryOwner> {
    const project = this.registry.get(projectId);
    const storage = new ProjectStorage();
    let bundle: BundleMetadataStore | undefined;
    if (project.storageKind === 'bundle') {
      const dataDirectory = this.registry.bundleDirectory(projectId);
      if (!fs.existsSync(path.join(dataDirectory, 'metadata.sqlite')))
        throw new Error('The saved project database is missing');
      const roots = this.registry.historyRoots(projectId);
      bundle = this.isReadOnly
        ? BundleMetadataStore.openReadOnly({
            directory: dataDirectory,
            project,
          })
        : await BundleMetadataStore.open({ directory: dataDirectory, project });
      for (const projectPath of roots) {
        storage.attach({
          projectPath,
          dataDirectory,
          cacheDirectory: path.join(this.registry.root, 'cache', projectId),
        });
      }
    }
    const history = new VariantHistoryService(
      new TreeStore(storage),
      undefined,
      { bundle },
    );
    return { history, storage, bundle };
  }
}
